/* =========================================================
   2. 文字の正規化（表記ゆれ吸収）
   ========================================================= */
const SMALL_KANA = { 'ぁ': 'あ', 'ぃ': 'い', 'ぅ': 'う', 'ぇ': 'え', 'ぉ': 'お', 'っ': 'つ', 'ゃ': 'や', 'ゅ': 'ゆ', 'ょ': 'よ', 'ゎ': 'わ', 'ゕ': 'か', 'ゖ': 'け' };

function normalize(str) {
  let s = String(str).normalize('NFKC').toUpperCase();
  s = s.replace(/[\u30A1-\u30F6]/g, (c) => String.fromCharCode(c.charCodeAt(0) - 0x60)); // カタカナ→ひらがな
  s = s.replace(/[\s・･ー\-―‐－~〜～、。.,!！?？'"「」『』]/g, '');                       // 記号・長音
  s = s.replace(/[ぁぃぅぇぉっゃゅょゎゕゖ]/g, (c) => SMALL_KANA[c]);                       // 小さい文字
  return s;
}
// 濁点・半濁点も無視する、さらにゆるい比較用
function loose(str) {
  return str.normalize('NFD').replace(/[\u3099\u309A]/g, '').normalize('NFC');
}
const isKanji = (c) => /[\u4E00-\u9FFF々]/.test(c);
const hasKanji = (s) => /[\u4E00-\u9FFF々]/.test(s);
const escRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/* =========================================================
   3. データの組み立て
   ========================================================= */
const MOVES = [];
const MOVE_BY_ID = new Map();
const KEY_MAP = new Map();   // 正規化した文字列 → 技
const VOICE_KEYS = [];       // { lkey, move }（音声のゆるい照合用）

function textOn(hex) {
  const n = parseInt(hex.slice(1), 16);
  const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  return (0.299 * r + 0.587 * g + 0.114 * b) / 255 > 0.62 ? '#1C2547' : '#FFFFFF';
}
TYPES.forEach((t) => { if (t) t.on = textOn(t.color); });

function addMove(id, name, gen, type) {
  id = Number(id); gen = Number(gen); type = Number(type);
  name = String(name || '').normalize('NFKC').trim();
  if (!id || !name || !TYPES[type] || !(gen >= 1) || MOVE_BY_ID.has(id)) return null;
  const move = { id, name, gen, type };
  MOVES.push(move);
  MOVE_BY_ID.set(move.id, move);
  [move.name].concat(NAME_ALIASES[move.name] || []).forEach((k) => {
    const key = normalize(k);
    if (!key) return;
    if (!KEY_MAP.has(key)) KEY_MAP.set(key, move);
    VOICE_KEYS.push({ lkey: loose(key), move });
  });
  return move;
}

MOVE_DATA.trim().split('\n').forEach((line) => {
  const p = line.split(',');
  if (p.length >= 4) addMove(p[0], p[1], p[2], p[3]);
});

function sortMoves() { MOVES.sort((a, b) => a.id - b.id); }
sortMoves();
const maxGen = () => Math.max(...MOVES.map((m) => m.gen));

// 漢字の読み表
function parseKanjiTable(text) {
  const map = new Map();
  text.split('|').forEach((entry) => {
    const chars = Array.from(entry);
    let i = 0;
    while (i < chars.length && !/[ぁ-ゖ]/.test(chars[i])) i++;
    const surface = chars.slice(0, i).join('');
    const readings = chars.slice(i).join('').split(',').filter(Boolean);
    if (surface && readings.length) map.set(surface, readings);
  });
  return map;
}
const KS = parseKanjiTable(KANJI_SINGLE);
const KC = parseKanjiTable(KANJI_COMPOUND);

/* =========================================================
   4. 保存（localStorage は失敗しても動くように）
   ========================================================= */
const STORE_PREFIX = 'wazaieru.';
const store = {
  get(key, fallback) {
    try {
      const v = localStorage.getItem(STORE_PREFIX + key);
      return v ? JSON.parse(v) : fallback;
    } catch (e) { return fallback; }
  },
  set(key, value) {
    try { localStorage.setItem(STORE_PREFIX + key, JSON.stringify(value)); } catch (e) { /* 保存できない環境 */ }
  },
  remove(key) {
    try { localStorage.removeItem(STORE_PREFIX + key); } catch (e) { /* noop */ }
  }
};

