/* =========================================================
   7. サウンド（Web Audio：効果音とBGMを全部コードで鳴らす）
   ========================================================= */
const audio = { ctx: null, master: null, se: null, bgm: null, noise: null };

function initAudio() {
  try {
    if (!audio.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      const ctx = new AC();
      audio.ctx = ctx;
      audio.master = ctx.createGain();
      audio.se = ctx.createGain();
      audio.bgm = ctx.createGain();
      audio.se.connect(audio.master);
      audio.bgm.connect(audio.master);
      audio.master.connect(ctx.destination);
      // ハイハット用のノイズ
      const len = Math.floor(ctx.sampleRate * 0.2);
      const buf = ctx.createBuffer(1, len, ctx.sampleRate);
      const data = buf.getChannelData(0);
      for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
      audio.noise = buf;
      applyVolume();
    }
    if (audio.ctx.state === 'suspended') audio.ctx.resume();
  } catch (e) { return null; }
  return audio.ctx;
}

function applyVolume() {
  if (!audio.ctx) return;
  const v = Math.pow(settings.volume / 100, 1.4) * 0.9;
  audio.master.gain.setTargetAtTime(v, audio.ctx.currentTime, 0.02);
  audio.se.gain.setTargetAtTime(settings.se ? 1 : 0, audio.ctx.currentTime, 0.02);
  const duck = voice.listening ? 0.3 : 1;
  audio.bgm.gain.setTargetAtTime(settings.bgm ? 0.55 * duck : 0, audio.ctx.currentTime, 0.05);
}

function tone(freq, start, dur, opts) {
  const ctx = audio.ctx;
  if (!ctx || !settings.se) return;
  const o = opts || {};
  const t0 = ctx.currentTime + start;
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = o.type || 'square';
  osc.frequency.setValueAtTime(freq, t0);
  if (o.slide) osc.frequency.exponentialRampToValueAtTime(o.slide, t0 + dur);
  const vol = o.vol || 0.08;
  gain.gain.setValueAtTime(0.0001, t0);
  gain.gain.exponentialRampToValueAtTime(vol, t0 + 0.008);
  gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  osc.connect(gain).connect(o.dest || audio.se);
  osc.start(t0);
  osc.stop(t0 + dur + 0.03);
}

function noiseHit(start, dur, vol, dest, hp) {
  const ctx = audio.ctx;
  if (!ctx || !audio.noise) return;
  const t0 = ctx.currentTime + start;
  const src = ctx.createBufferSource();
  src.buffer = audio.noise;
  const filter = ctx.createBiquadFilter();
  filter.type = 'highpass';
  filter.frequency.value = hp || 6000;
  const gain = ctx.createGain();
  gain.gain.setValueAtTime(vol, t0);
  gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  src.connect(filter).connect(gain).connect(dest || audio.se);
  src.start(t0);
  src.stop(t0 + dur + 0.02);
}

const NOTE = (n) => 440 * Math.pow(2, (n - 69) / 12); // MIDI番号→周波数

const sfx = {
  ok(combo) {
    const base = 72 + Math.min(combo - 1, 12); // コンボで音程が上がる
    tone(NOTE(base), 0, 0.07);
    tone(NOTE(base + 7), 0.06, 0.07);
    tone(NOTE(base + 12), 0.12, 0.14, { vol: 0.07 });
  },
  ng() { tone(196, 0, 0.16, { type: 'sawtooth', vol: 0.05, slide: 150 }); },
  dup() { tone(NOTE(76), 0, 0.06, { type: 'triangle' }); tone(NOTE(76), 0.09, 0.06, { type: 'triangle' }); },
  click() { tone(NOTE(84), 0, 0.03, { type: 'triangle', vol: 0.04 }); },
  count() { tone(NOTE(76), 0, 0.12, { vol: 0.07 }); },
  go() { [72, 76, 79, 84].forEach((n) => tone(NOTE(n), 0, 0.35, { vol: 0.05 })); noiseHit(0, 0.2, 0.06, null, 3000); },
  tick() { tone(NOTE(88), 0, 0.04, { type: 'triangle', vol: 0.06 }); },
  milestone() { [79, 84, 88].forEach((n, i) => tone(NOTE(n), i * 0.07, 0.12)); },
  groupDone() {
    [72, 76, 79, 84, 88, 91].forEach((n, i) => tone(NOTE(n), i * 0.06, 0.15, { vol: 0.07 }));
    noiseHit(0.36, 0.3, 0.05, null, 4000);
  },
  timeUp() { [79, 74, 71, 67].forEach((n, i) => tone(NOTE(n), i * 0.12, 0.2, { type: 'triangle', vol: 0.1 })); },
  result(good) {
    const seq = good ? [72, 76, 79, 84, 79, 84, 88] : [72, 76, 79, 84];
    seq.forEach((n, i) => tone(NOTE(n), i * 0.11, 0.24, { type: 'triangle', vol: 0.1 }));
    if (good) [84, 88, 91].forEach((n) => tone(NOTE(n), seq.length * 0.11, 0.6, { vol: 0.04 }));
  },
  mic(on) { tone(NOTE(on ? 79 : 72), 0, 0.06, { type: 'triangle' }); tone(NOTE(on ? 86 : 67), 0.06, 0.08, { type: 'triangle' }); }
};

// ---- BGM（ゆるいチップチューン。残り30秒でテンポアップ） ----
const bgm = {
  playing: false,
  timerId: 0,
  step: 0,
  nextTime: 0,
  bpm: 126,
  hurry: false,
  // コード進行（ルート音のMIDI番号と3和音）
  chords: [[48, [60, 64, 67]], [45, [57, 60, 64]], [41, [57, 60, 65]], [43, [55, 59, 62]],
           [48, [60, 64, 67]], [45, [57, 60, 64]], [50, [57, 62, 65]], [43, [55, 59, 62]]],
  start() {
    if (!audio.ctx || this.playing) return;
    this.playing = true;
    this.step = 0;
    this.nextTime = audio.ctx.currentTime + 0.08;
    this.timerId = setInterval(() => this.schedule(), 25);
  },
  stop() {
    this.playing = false;
    clearInterval(this.timerId);
    this.timerId = 0;
  },
  setHurry(on) { this.hurry = on; this.bpm = on ? 158 : 126; },
  schedule() {
    const ctx = audio.ctx;
    if (!ctx || !this.playing) return;
    const stepDur = 60 / this.bpm / 4; // 16分音符
    while (this.nextTime < ctx.currentTime + 0.15) {
      this.playStep(this.step, this.nextTime - ctx.currentTime, stepDur);
      this.nextTime += stepDur;
      this.step = (this.step + 1) % (16 * this.chords.length);
    }
  },
  playStep(step, at, dur) {
    if (!settings.bgm) return;
    const bar = Math.floor(step / 16) % this.chords.length;
    const s = step % 16;
    const [root, triad] = this.chords[bar];
    const dest = { dest: audio.bgm };
    // ベース（8分）
    if (s % 2 === 0) {
      const n = s % 4 === 0 ? root : root + 12;
      tone(NOTE(n), at, dur * 1.7, Object.assign({ type: 'triangle', vol: 0.12 }, dest));
    }
    // アルペジオ（16分）
    const arp = [0, 1, 2, 1, 0, 2, 1, 2];
    const n2 = triad[arp[s % 8]] + 12 + (s >= 8 && bar % 2 === 1 ? 12 : 0);
    tone(NOTE(n2), at, dur * 0.9, Object.assign({ type: 'square', vol: 0.022 }, dest));
    // メロディっぽい合いの手
    if (s === 0 || s === 6 || s === 10) {
      tone(NOTE(triad[2] + 12), at, dur * 2.5, Object.assign({ type: 'square', vol: 0.03 }, dest));
    }
    // ハイハット
    if (s % 2 === 1) noiseHit(at, 0.04, this.hurry ? 0.05 : 0.035, audio.bgm, 7000);
    if (s % 8 === 4) noiseHit(at, 0.12, 0.05, audio.bgm, 1800);
  }
};

