function speakName(name) {
  if (!settings.speak || voice.wanted || !('speechSynthesis' in window)) return;
  try {
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(name);
    u.lang = 'ja-JP';
    u.rate = 1.15;
    u.volume = Math.max(0.1, settings.volume / 100);
    window.speechSynthesis.speak(u);
  } catch (e) { /* 非対応 */ }
}

/* =========================================================
   8. 演出（パーティクル・紙吹雪）
   ========================================================= */
const fx = {
  ctx: null, w: 0, h: 0, dpr: 1, parts: [], raf: 0,
  init() {
    this.ctx = el.fx.getContext('2d');
    this.resize();
    window.addEventListener('resize', () => this.resize());
  },
  resize() {
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.w = window.innerWidth;
    this.h = window.innerHeight;
    el.fx.width = Math.floor(this.w * this.dpr);
    el.fx.height = Math.floor(this.h * this.dpr);
  },
  burst(x, y, colors, count, power) {
    if (REDUCED_MOTION || !this.ctx) return;
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = (power || 5) * (0.4 + Math.random() * 0.8);
      this.parts.push({
        x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 2,
        g: 0.18, life: 1, decay: 0.018 + Math.random() * 0.02,
        size: 3 + Math.random() * 4, rot: Math.random() * 6, vr: (Math.random() - 0.5) * 0.4,
        color: colors[i % colors.length], shape: Math.random() < 0.5 ? 0 : 1
      });
    }
    this.run();
  },
  confetti(count) {
    if (REDUCED_MOTION || !this.ctx) return;
    const colors = TYPE_ORDER.map((t) => TYPES[t].color);
    for (let i = 0; i < count; i++) {
      this.parts.push({
        x: Math.random() * this.w, y: -20 - Math.random() * this.h * 0.4,
        vx: (Math.random() - 0.5) * 2, vy: 2 + Math.random() * 3,
        g: 0.04, life: 1, decay: 0.004 + Math.random() * 0.004,
        size: 5 + Math.random() * 5, rot: Math.random() * 6, vr: (Math.random() - 0.5) * 0.3,
        color: colors[i % colors.length], shape: 1
      });
    }
    this.run();
  },
  run() {
    if (this.raf) return;
    const loop = () => {
      const c = this.ctx;
      c.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
      c.clearRect(0, 0, this.w, this.h);
      this.parts = this.parts.filter((p) => p.life > 0 && p.y < this.h + 40);
      this.parts.forEach((p) => {
        p.vy += p.g; p.x += p.vx; p.y += p.vy; p.vx *= 0.99;
        p.rot += p.vr; p.life -= p.decay;
        c.globalAlpha = Math.max(0, Math.min(1, p.life * 1.5));
        c.fillStyle = p.color;
        if (p.shape === 0) {
          c.beginPath(); c.arc(p.x, p.y, p.size / 2, 0, Math.PI * 2); c.fill();
        } else {
          c.save(); c.translate(p.x, p.y); c.rotate(p.rot);
          c.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2);
          c.restore();
        }
      });
      c.globalAlpha = 1;
      if (this.parts.length) {
        this.raf = requestAnimationFrame(loop);
      } else {
        this.raf = 0;
        c.clearRect(0, 0, this.w, this.h);
      }
    };
    this.raf = requestAnimationFrame(loop);
  }
};

function centerOf(node) {
  const r = node.getBoundingClientRect();
  return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
}

function toast(text, gold) {
  const t = document.createElement('div');
  t.className = 'toast' + (gold ? ' gold' : '');
  t.textContent = text;
  el.toastArea.appendChild(t);
  setTimeout(() => t.remove(), 2400);
  while (el.toastArea.children.length > 3) el.toastArea.firstChild.remove();
}

function showBanner(text, gold, ms) {
  return new Promise((resolve) => {
    el.bannerText.textContent = text;
    el.banner.classList.toggle('gold', !!gold);
    el.banner.hidden = false;
    // アニメーションを毎回やり直す
    el.bannerText.style.animation = 'none';
    void el.bannerText.offsetWidth;
    el.bannerText.style.animation = '';
    setTimeout(() => { el.banner.hidden = true; resolve(); }, ms || 1300);
  });
}

/* =========================================================
   9. 出題範囲
   ========================================================= */
function scopeFrom(kind, gen, type) {
  if (kind === 'gen') return { kind, value: gen };
  if (kind === 'type') return { kind, value: type };
  return { kind: 'all', value: 0 };
}
function scopeMoves(scope) {
  if (scope.kind === 'gen') return MOVES.filter((m) => m.gen === scope.value);
  if (scope.kind === 'type') return MOVES.filter((m) => m.type === scope.value);
  return MOVES.slice();
}
function scopeLabel(scope) {
  if (scope.kind === 'gen') return GEN_LABEL(scope.value);
  if (scope.kind === 'type') return `${TYPES[scope.value].name}タイプ`;
  return '全部の技';
}
function limitLabel(sec) {
  const t = TIME_OPTIONS.find((o) => o.sec === sec);
  return sec === 0 ? '時間無制限' : (t ? t.label : `${Math.round(sec / 60)}分`);
}
function bestKey(scope, limit) { return `${scope.kind}-${scope.value}-${limit}`; }

/* =========================================================
   10. タイトル画面
   ========================================================= */
function buildHeroMosaic() {
  el.heroMosaic.textContent = '';
  const frag = document.createDocumentFragment();
  MOVES.filter((_, i) => i % 3 === 0).forEach((m, i) => {
    const d = document.createElement('i');
    d.style.setProperty('--c', TYPES[m.type].color);
    frag.appendChild(d);
    if (i % 4 === 0 || i % 7 === 0) setTimeout(() => d.classList.add('lit'), 200 + i * 6);
  });
  el.heroMosaic.appendChild(frag);
}

function makeChip(label, sub, checked, onClick, color) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'chip';
  b.setAttribute('role', 'radio');
  b.setAttribute('aria-checked', String(checked));
  b.textContent = label;
  if (sub !== '') {
    const s = document.createElement('small');
    s.textContent = sub;
    b.appendChild(s);
  }
  if (color) {
    b.style.setProperty('--c', color.color);
    b.style.setProperty('--on-c', color.on);
  }
  b.addEventListener('click', onClick);
  return b;
}

function renderSetup() {
  el.totalCount.textContent = MOVES.length;
  el.segKind.querySelectorAll('button').forEach((b) => {
    b.setAttribute('aria-checked', String(b.dataset.kind === settings.kind));
  });
  el.chipsGen.hidden = settings.kind !== 'gen';
  el.chipsType.hidden = settings.kind !== 'type';
  el.allNote.hidden = settings.kind !== 'all';

  el.chipsGen.textContent = '';
  for (let g = 1; g <= maxGen(); g++) {
    const count = MOVES.filter((m) => m.gen === g).length;
    el.chipsGen.appendChild(makeChip(GEN_LABEL(g), `${count}`, settings.gen === g, () => {
      settings.gen = g; saveSettings(); renderSetup();
    }));
  }

  el.chipsType.textContent = '';
  TYPE_ORDER.forEach((t) => {
    const count = MOVES.filter((m) => m.type === t).length;
    el.chipsType.appendChild(makeChip(TYPES[t].name, `${count}`, settings.type === t, () => {
      settings.type = t; saveSettings(); renderSetup();
    }, TYPES[t]));
  });

  el.chipsTime.textContent = '';
  TIME_OPTIONS.forEach((o) => {
    el.chipsTime.appendChild(makeChip(o.label, '', settings.limit === o.sec, () => {
      settings.limit = o.sec; saveSettings(); renderSetup();
    }));
  });

  el.optVoice.checked = settings.voice && voice.supported;
  el.optVoice.disabled = !voice.supported;
  el.voiceSupport.textContent = voice.supported
    ? '開始時にマイクの許可を求められます'
    : 'このブラウザは音声入力に対応していません（Chrome・Edge・Safari推奨）';
  el.optHint.checked = settings.hint;
  el.optDetail.checked = settings.detail;
  el.optSe.checked = settings.se;
  el.optBgm.checked = settings.bgm;
  el.optSpeak.checked = settings.speak;
  el.optVolume.value = settings.volume;
  el.volumeVal.textContent = settings.volume;

  const scope = scopeFrom(settings.kind, settings.gen, settings.type);
  const total = scopeMoves(scope).length;
  const best = store.get('best', {})[bestKey(scope, settings.limit)];
  if (best) {
    let text = `自己ベスト（${scopeLabel(scope)}・${limitLabel(settings.limit)}）：${best.count} / ${total}`;
    if (best.count >= total && best.timeMs) text += `（${formatTime(best.timeMs)}）`;
    el.bestLine.textContent = text;
  } else {
    el.bestLine.textContent = `${scopeLabel(scope)}・${limitLabel(settings.limit)}：全${total}個`;
  }
}

function renderResume() {
  const save = store.get('save', null);
  if (!save || !isValidSave(save)) {
    el.resumeCard.hidden = true;
    if (save) store.remove('save');
    return;
  }
  const total = scopeMoves(save.scope).length;
  let meta = `${scopeLabel(save.scope)}・${save.found.length} / ${total}個`;
  if (save.limit > 0) meta += `・残り ${formatTime(Math.max(0, save.limit * 1000 - save.elapsed), true)}`;
  else meta += `・経過 ${formatTime(save.elapsed)}`;
  el.resumeMeta.textContent = meta;
  el.resumeCard.hidden = false;
}

function isValidSave(s) {
  return s && s.scope && ['gen', 'type', 'all'].includes(s.scope.kind)
    && Array.isArray(s.found) && typeof s.elapsed === 'number'
    && typeof s.limit === 'number' && scopeMoves(s.scope).length > 0;
}

function showScreen(name) {
  el.screenTitle.classList.toggle('is-active', name === 'title');
  el.screenGame.classList.toggle('is-active', name === 'game');
  window.scrollTo(0, 0);
}

function goTitle() {
  if (game) {
    stopTimer();
    clearTimeout(game.cdTimer);
    clearTimeout(game.comboTimer);
    game.ended = true;
  }
  voiceSuspend();
  bgm.stop();
  game = null;
  el.countdown.hidden = true;
  el.banner.hidden = true;
  hideAllOverlays();
  renderSetup();
  renderResume();
  showScreen('title');
}

/* =========================================================
   11. PokéAPI（技の説明・新しい技の自動取り込み）
   ========================================================= */
const API = 'https://pokeapi.co/api/v2';
const detailCache = new Map(Object.entries(store.get('detail', {})));
const detailInflight = new Map();
let detailSaveTimer = 0;

function fetchJson(url, ms) {
  const ctrl = 'AbortController' in window ? new AbortController() : null;
  const timer = setTimeout(() => { if (ctrl) ctrl.abort(); }, ms || 8000);
  return fetch(url, ctrl ? { signal: ctrl.signal } : undefined)
    .then((r) => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); })
    .finally(() => clearTimeout(timer));
}

function pickJaText(entries, field) {
  if (!Array.isArray(entries)) return '';
  const byLang = (lang) => entries.filter((e) => e.language && e.language.name === lang);
  const list = byLang('ja-Hrkt').length ? byLang('ja-Hrkt') : byLang('ja');
  if (!list.length) return '';
  return String(list[list.length - 1][field] || '').replace(/[\n\f\r]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function getDetail(id) {
  const key = String(id);
  if (detailCache.has(key)) return Promise.resolve(detailCache.get(key));
  if (detailInflight.has(key)) return detailInflight.get(key);
  const p = fetchJson(`${API}/move/${id}/`).then((d) => {
    const en = (d.names || []).find((n) => n.language && n.language.name === 'en');
    const info = {
      p: d.power, a: d.accuracy, pp: d.pp, pr: d.priority,
      c: d.damage_class ? d.damage_class.name : '',
      d: pickJaText(d.flavor_text_entries, 'flavor_text'),
      en: en ? en.name : ''
    };
    detailCache.set(key, info);
    clearTimeout(detailSaveTimer);
    detailSaveTimer = setTimeout(() => store.set('detail', Object.fromEntries(detailCache)), 1000);
    return info;
  }).finally(() => detailInflight.delete(key));
  detailInflight.set(key, p);
  return p;
}

function idFromUrl(url) {
  const m = /\/(\d+)\/?$/.exec(url || '');
  return m ? Number(m[1]) : 0;
}

// PokéAPIに新しい技が増えていたら自動で取り込む（3日に1回チェック）
async function checkNewMoves() {
  const extra = store.get('extra', null);
  if (extra && Date.now() - extra.at < 3 * 24 * 3600 * 1000) {
    setApiStatus(extra.moves.length ? `PokéAPIから取り込んだ新しい技：${extra.moves.length}個` : '', false);
    return;
  }
  setApiStatus('PokéAPIで最新の技データを確認中…', false);
  try {
    const list = await fetchJson(`${API}/move?limit=3000`, 10000);
    const ids = (list.results || []).map((r) => idFromUrl(r.url))
      .filter((id) => id > BUILTIN_MAX_ID && id < 10000 && !MOVE_BY_ID.has(id))
      .slice(0, 40);
    const added = (extra && Array.isArray(extra.moves)) ? extra.moves.slice() : [];
    for (const id of ids) {
      try {
        const d = await fetchJson(`${API}/move/${id}/`);
        const name = pickJaText(d.names, 'name');
        const gen = idFromUrl(d.generation && d.generation.url);
        const type = idFromUrl(d.type && d.type.url);
        // ダイマックス技などの特殊な技は除外（PP1の専用技・ダイ〇〇）
        const special = d.pp === 1 || /^max-|^g-max-/.test(d.name || '');
        if (name && gen && TYPES[type] && !special) {
          if (addMove(id, name, gen, type)) added.push({ id, name: name.normalize('NFKC'), gen, type });
        }
      } catch (e) { /* 1件失敗しても続ける */ }
    }
    sortMoves();
    store.set('extra', { at: Date.now(), moves: added });
    if (ids.length && added.length) {
      setApiStatus(`PokéAPIから新しい技を取り込みました（追加 ${added.length}個・全${MOVES.length}個）`, true);
      if (el.screenTitle.classList.contains('is-active')) { buildHeroMosaic(); renderSetup(); }
    } else {
      setApiStatus('技データは最新です（PokéAPIで確認済み）', false);
    }
  } catch (e) {
    setApiStatus('オフラインのため、内蔵の技データで遊べます', false);
  }
}
function setApiStatus(text, isNew) {
  el.apiStatus.textContent = text;
  el.apiStatus.classList.toggle('new', !!isNew);
}

/* =========================================================
   12. ゲーム開始・ボード
   ========================================================= */
function startGame(opts) {
  if (game) { stopTimer(); clearTimeout(game.cdTimer); clearTimeout(game.comboTimer); }
  const scope = opts.scope;
  const targets = scopeMoves(scope);
  const targetIds = new Set(targets.map((m) => m.id));
  const found = (opts.found || []).filter((id) => targetIds.has(id));

  game = {
    scope,
    limit: opts.limit,
    hint: opts.hint,
    targets,
    targetIds,
    found: new Set(found),
    order: found.slice(),
    elapsed: opts.elapsed || 0,
    lastTick: 0,
    running: false,
    paused: false,
    ended: false,
    combo: 0,
    maxCombo: opts.maxCombo || 0,
    lastCorrectAt: 0,
    comboTimer: 0,
    cdTimer: 0,
    milestones: new Set(),
    lastTickSec: -1,
    tileEls: new Map(),
    groupEls: new Map(),
    timerId: 0,
    lastSaveAt: 0
  };
  // 再開時は、すでに通過した節目のお知らせを出さない
  [25, 50, 75].forEach((p) => { if (found.length / targets.length * 100 >= p) game.milestones.add(p); });

  buildBoard();
  el.countTotal.textContent = targets.length;
  el.statScope.textContent = `${scopeLabel(scope)}・${limitLabel(game.limit)}`;
  el.inputRow.hidden = false;
  el.feedback.hidden = false;
  el.reviewRow.hidden = true;
  el.reviewTip.hidden = true;
  el.lastCard.hidden = true;
  el.board.classList.remove('only-missed');
  el.onlyMissed.setAttribute('aria-pressed', 'false');
  el.answer.value = '';
  el.answer.disabled = false;
  el.combo.classList.remove('show');
  el.mic.hidden = !voice.supported;
  bgm.setHurry(false);
  setFeedback(voice.wanted ? 'マイクに向かって技名を言ってね。キーボード入力もできます。' : 'ひらがな・カタカナどちらでもOK。ぴったり合えば自動で入ります。', '');
  updateStats();
  hideAllOverlays();
  showScreen('game');
  saveProgress();
  runCountdown();
}

function runCountdown() {
  const seq = ['3', '2', '1', 'スタート！'];
  let i = 0;
  el.countdown.hidden = false;
  const next = () => {
    if (!game || game.ended) { el.countdown.hidden = true; return; }
    const label = seq[i];
    el.cdNum.textContent = label;
    el.cdNum.classList.toggle('go', i === seq.length - 1);
    el.cdNum.classList.remove('tick');
    void el.cdNum.offsetWidth;
    el.cdNum.classList.add('tick');
    if (i < seq.length - 1) sfx.count(); else sfx.go();
    i++;
    if (i < seq.length) {
      game.cdTimer = setTimeout(next, 650);
    } else {
      game.cdTimer = setTimeout(() => {
        el.countdown.hidden = true;
        if (!game || game.ended) return;
        resumeTimer();
        bgm.start();
        if (voice.wanted) voiceListen();
        tryAutoAccept(); // カウントダウン中に打っていた分を判定
      }, 500);
    }
  };
  next();
}

function groupKeyOf(move) {
  return game.scope.kind === 'gen' ? 'all' : `g${move.gen}`;
}

function buildBoard() {
  el.board.textContent = '';
  el.board.classList.toggle('hint', game.hint);
  el.board.classList.remove('is-hidden');

  const groups = new Map();
  game.targets.forEach((m) => {
    const key = groupKeyOf(m);
    if (!groups.has(key)) groups.set(key, { title: key === 'all' ? scopeLabel(game.scope) : GEN_LABEL(m.gen), moves: [] });
    groups.get(key).moves.push(m);
  });

  const frag = document.createDocumentFragment();
  groups.forEach((g, key) => {
    const sec = document.createElement('section');
    sec.className = 'group';
    const head = document.createElement('h2');
    head.className = 'group-head';
    head.textContent = g.title;
    const cnt = document.createElement('span');
    head.appendChild(cnt);
    const tiles = document.createElement('div');
    tiles.className = 'tiles';

    g.moves.forEach((m) => {
      const t = document.createElement('div');
      t.className = 'tile';
      t.dataset.id = m.id;
      t.style.setProperty('--c', TYPES[m.type].color);
      t.style.setProperty('--on-c', TYPES[m.type].on);
      const no = document.createElement('span');
      no.className = 'no';
      no.textContent = `No.${String(m.id).padStart(3, '0')}`;
      const nm = document.createElement('span');
      nm.className = 'nm';
      t.appendChild(no);
      t.appendChild(nm);
      tiles.appendChild(t);
      game.tileEls.set(m.id, t);
      if (game.found.has(m.id)) {
        t.classList.add('found');
        nm.textContent = m.name;
      }
    });

    sec.appendChild(head);
    sec.appendChild(tiles);
    frag.appendChild(sec);
    game.groupEls.set(key, { sec, cnt, title: g.title, total: g.moves.length, ids: g.moves.map((m) => m.id) });
  });
  el.board.appendChild(frag);
  game.groupEls.forEach((_, key) => updateGroup(key));
}

function updateGroup(key) {
  const g = game.groupEls.get(key);
  if (!g) return false;
  let n = 0;
  g.ids.forEach((id) => { if (game.found.has(id)) n++; });
  g.cnt.textContent = `${n} / ${g.total}`;
  const done = n === g.total;
  const was = g.sec.classList.contains('done');
  g.sec.classList.toggle('done', done);
  return done && !was;
}

function updateStats() {
  el.countNow.textContent = game.found.size;
  const pct = game.targets.length ? (game.found.size / game.targets.length) * 100 : 0;
  el.progressBar.style.width = `${pct}%`;
  renderTimer();
}

/* =========================================================
   13. タイマー
   ========================================================= */
function resumeTimer() {
  if (!game || game.ended) return;
  game.running = true;
  game.paused = false;
  game.lastTick = performance.now();
  stopInterval();
  game.timerId = setInterval(tick, 200);
  renderTimer();
}
function stopInterval() {
  if (game && game.timerId) { clearInterval(game.timerId); game.timerId = 0; }
}
function stopTimer() {
  if (!game) return;
  if (game.running) accumulate();
  game.running = false;
  stopInterval();
}
function accumulate() {
  const now = performance.now();
  game.elapsed += Math.max(0, now - game.lastTick);
  game.lastTick = now;
}
function tick() {
  if (!game || !game.running) return;
  accumulate();
  renderTimer();
  if (game.limit > 0) {
    const remain = game.limit * 1000 - game.elapsed;
    if (remain <= 0) {
      game.elapsed = game.limit * 1000;
      endGame('timeup');
      return;
    }
    // 残り30秒でBGMテンポアップ、残り10秒はカウント音
    if (remain <= 30000 && !bgm.hurry) { bgm.setHurry(true); toast('残り30秒！'); }
    const sec = Math.ceil(remain / 1000);
    if (sec <= 10 && sec !== game.lastTickSec) { game.lastTickSec = sec; sfx.tick(); }
  }
  if (performance.now() - game.lastSaveAt > 5000) saveProgress();
}
function renderTimer() {
  if (!game) return;
  if (game.limit > 0) {
    const remain = Math.max(0, game.limit * 1000 - game.elapsed);
    el.statTimer.textContent = formatTime(remain, true);
    el.statTimer.classList.toggle('warn', remain <= 30000 && !game.ended);
  } else {
    el.statTimer.textContent = formatTime(game.elapsed);
    el.statTimer.classList.remove('warn');
  }
}
function formatTime(ms, ceil) {
  const total = ceil ? Math.ceil(ms / 1000) : Math.floor(ms / 1000);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  const ss = String(s).padStart(2, '0');
  return h > 0 ? `${h}:${String(m).padStart(2, '0')}:${ss}` : `${m}:${ss}`;
}

/* =========================================================
   14. キーボード入力と判定
   ========================================================= */
let composing = false;

function setFeedback(text, kind) {
  el.feedback.textContent = text;
  el.feedback.className = 'feedback' + (kind ? ` ${kind}` : '');
}

function focusAnswer() {
  // スマホはタッチ操作の流れでないとキーボードが出ないので、PCのみ自動フォーカス
  if (window.matchMedia('(pointer: fine)').matches) setTimeout(() => el.answer.focus(), 30);
}

// 入力途中：未回答の技とぴったり一致したら自動で正解
function tryAutoAccept() {
  if (!game || !game.running || composing) return;
  const key = normalize(el.answer.value);
  if (!key) return;
  const move = KEY_MAP.get(key);
  if (move && game.targetIds.has(move.id) && !game.found.has(move.id)) {
    accept(move);
    clearAnswer(move);
  }
}

// iOSの変換確定直後は値の書き換えが効かないことがあるので2段階で消す
function clearAnswer(move) {
  el.answer.value = '';
  setTimeout(() => { if (move && normalize(el.answer.value) === normalize(move.name)) el.answer.value = ''; }, 0);
}

// 決定ボタン・Enter：一致しない理由も教える
function submitAnswer() {
  if (!game || !game.running) return;
  const raw = el.answer.value;
  const key = normalize(raw);
  if (!key) return;
  const move = KEY_MAP.get(key);
  if (!move) { reject(`「${raw.trim()}」という技は見つかりません`, 'ng'); return; }
  if (!game.targetIds.has(move.id)) { reject(outOfScopeText(move), 'ng'); return; }
  if (game.found.has(move.id)) {
    reject(`「${move.name}」はもう答えています`, 'dup');
    flashTile(move.id);
    return;
  }
  accept(move);
  clearAnswer(move);
}

function outOfScopeText(move) {
  const where = game.scope.kind === 'gen' ? GEN_LABEL(move.gen) : `${TYPES[move.type].name}タイプ`;
  return `「${move.name}」は今回の範囲外です（${where}）`;
}

function reject(msg, kind, fromVoice) {
  setFeedback(msg, 'ng');
  if (kind === 'dup') sfx.dup(); else sfx.ng();
  if (!fromVoice) {
    el.answer.classList.remove('shake', 'good');
    void el.answer.offsetWidth;
    el.answer.classList.add('shake');
    el.answer.select();
  }
}

function accept(move, fromVoice) {
  if (!game || game.found.has(move.id)) return;
  game.found.add(move.id);
  game.order.push(move.id);

  // コンボ
  const now = performance.now();
  game.combo = (now - game.lastCorrectAt <= COMBO_MS) ? game.combo + 1 : 1;
  game.lastCorrectAt = now;
  game.maxCombo = Math.max(game.maxCombo, game.combo);
  showCombo();

  const tile = game.tileEls.get(move.id);
  if (tile) {
    tile.classList.add('found', 'fresh');
    tile.querySelector('.nm').textContent = move.name;
    setTimeout(() => tile.classList.remove('fresh'), 400);
  }

  const groupKey = groupKeyOf(move);
  const groupDone = updateGroup(groupKey);
  updateStats();
  el.countNow.classList.remove('bump');
  void el.countNow.offsetWidth;
  el.countNow.classList.add('bump');

  setFeedback(`${fromVoice ? '聞き取り成功！ ' : ''}○ ${move.name}`, 'ok');
  el.answer.classList.remove('shake');
  el.answer.classList.add('good');
  setTimeout(() => el.answer.classList.remove('good'), 300);

  // 演出：カウンターからタイプ色のパーティクル
  const c = centerOf(el.countNow);
  fx.burst(c.x, c.y, [TYPES[move.type].color, '#F2B705', '#FFFFFF'], 14 + Math.min(game.combo, 10) * 2, 4 + Math.min(game.combo, 8) * 0.4);

  if (groupDone && game.groupEls.size > 1) {
    sfx.groupDone();
    toast(`${game.groupEls.get(groupKey).title} コンプリート！`, true);
    fx.confetti(70);
  } else {
    sfx.ok(game.combo);
  }
  checkMilestones();
  showLastCard(move);
  speakName(move.name);

  saveProgress();
  if (game.found.size >= game.targets.length) endGame('complete');
}

function checkMilestones() {
  const total = game.targets.length;
  const n = game.found.size;
  if (n >= total) return;
  const pct = (n / total) * 100;
  [25, 50, 75].forEach((p) => {
    if (pct >= p && !game.milestones.has(p)) {
      game.milestones.add(p);
      toast(`${p}% 達成！`);
      sfx.milestone();
    }
  });
  const left = total - n;
  if (total >= 20 && left === 10 && !game.milestones.has('left10')) {
    game.milestones.add('left10');
    toast('残り10個！', true);
  }
}

function showCombo() {
  clearTimeout(game.comboTimer);
  if (game.combo >= 2) {
    el.comboNum.textContent = game.combo;
    el.combo.classList.add('show');
    el.combo.classList.remove('pop');
    void el.combo.offsetWidth;
    el.combo.classList.add('pop');
    el.comboBar.classList.remove('run');
    el.comboBar.style.setProperty('--combo-ms', `${COMBO_MS}ms`);
    void el.comboBar.offsetWidth;
    el.comboBar.classList.add('run');
    if (game.combo % 10 === 0) toast(`${game.combo}コンボ！`, true);
  } else {
    el.combo.classList.remove('show');
  }
  game.comboTimer = setTimeout(() => { el.combo.classList.remove('show'); if (game) game.combo = 0; }, COMBO_MS);
}

function resetCombo() {
  if (!game) return;
  clearTimeout(game.comboTimer);
  game.combo = 0;
  game.lastCorrectAt = 0;
  el.combo.classList.remove('show');
}

// 直前に正解した技のカード（説明はPokéAPIから）
function showLastCard(move) {
  if (!settings.detail) { el.lastCard.hidden = true; return; }
  const t = TYPES[move.type];
  el.lastCard.hidden = false;
  el.lastCard.dataset.id = move.id;
  el.lastCard.style.setProperty('--c', t.color);
  el.lastCard.style.setProperty('--on-c', t.on);
  el.lcType.textContent = t.name;
  el.lcName.textContent = move.name;
  el.lcMeta.textContent = GEN_LABEL(move.gen);
  el.lcDesc.textContent = '説明を読み込み中…';
  el.lastCard.style.animation = 'none';
  void el.lastCard.offsetWidth;
  el.lastCard.style.animation = '';
  getDetail(move.id).then((d) => {
    if (el.lastCard.dataset.id !== String(move.id)) return;
    el.lcMeta.textContent = [GEN_LABEL(move.gen), DAMAGE_CLASS[d.c] || '', d.p ? `威力${d.p}` : '', d.a ? `命中${d.a}` : ''].filter(Boolean).join('・');
    el.lcDesc.textContent = d.d || '説明文はありません';
  }).catch(() => {
    if (el.lastCard.dataset.id !== String(move.id)) return;
    el.lcDesc.textContent = '説明を取得できませんでした（オフライン）';
  });
}

function flashTile(id) {
  const t = game.tileEls.get(id);
  if (!t) return;
  t.classList.add('flash');
  t.scrollIntoView({ block: 'nearest', behavior: REDUCED_MOTION ? 'auto' : 'smooth' });
  setTimeout(() => t.classList.remove('flash'), 900);
}

/* =========================================================
   15. 音声入力（Web Speech API）
   ========================================================= */
const SpeechRec = window.SpeechRecognition || window.webkitSpeechRecognition;
const voice = {
  supported: !!SpeechRec,
  rec: null,
  wanted: false,     // ユーザーが音声入力をONにしているか
  listening: false,  // 実際にマイクが動いているか
  restartTimer: 0,
  fails: 0,
  startedAt: 0
};

function createRecognizer() {
  const rec = new SpeechRec();
  rec.lang = 'ja-JP';
  rec.continuous = true;
  rec.interimResults = true;
  rec.maxAlternatives = 5;

  rec.onstart = () => { voice.listening = true; updateMicUI(); applyVolume(); };
  rec.onspeechstart = () => el.mic.classList.add('hearing');
  rec.onspeechend = () => el.mic.classList.remove('hearing');

  rec.onresult = (e) => {
    for (let i = e.resultIndex; i < e.results.length; i++) {
      const res = e.results[i];
      if (!res || !res[0]) continue;
      if (res.isFinal) {
        const alts = [];
        for (let j = 0; j < res.length; j++) alts.push(res[j].transcript);
        handleVoice(alts);
      } else if (game && game.running) {
        setFeedback(`聞き取り中：${res[0].transcript}`, 'voice');
      }
    }
  };

  rec.onerror = (e) => {
    const err = e.error;
    if (err === 'not-allowed' || err === 'service-not-allowed') {
      voiceOff();
      setFeedback('マイクの使用が許可されていません。ブラウザの設定を確認してください', 'ng');
      toast('マイクが使えません');
    } else if (err === 'audio-capture') {
      voiceOff();
      setFeedback('マイクが見つかりません', 'ng');
    } else if (err === 'network') {
      setFeedback('音声認識の通信に失敗しました。キーボードでも答えられます', 'ng');
    }
    // no-speech / aborted は自動で再開するので何もしない
  };

  rec.onend = () => {
    voice.listening = false;
    el.mic.classList.remove('hearing');
    applyVolume();
    updateMicUI();
    if (voice.wanted && game && game.running && !game.ended) {
      const quick = performance.now() - voice.startedAt < 1500;
      voice.fails = quick ? voice.fails + 1 : 0;
      if (voice.fails >= 5) {
        voice.fails = 0;
        el.mic.classList.add('error');
        setFeedback('音声入力が止まりました。マイクボタンを押すと再開します', 'ng');
        return;
      }
      clearTimeout(voice.restartTimer);
      voice.restartTimer = setTimeout(voiceListen, quick ? 700 : 120);
    }
  };
  return rec;
}

function voiceListen() {
  if (!voice.supported || !voice.wanted || voice.listening) return;
  if (!voice.rec) voice.rec = createRecognizer();
  try {
    voice.rec.start();
    voice.startedAt = performance.now();
    el.mic.classList.remove('error');
  } catch (e) { /* すでに開始している */ }
}

function voiceOn() {
  if (!voice.supported) return;
  voice.wanted = true;
  voice.fails = 0;
  settings.voice = true;
  saveSettings();
  voiceListen();
  updateMicUI();
  applyVolume();
}

function voiceOff() {
  voice.wanted = false;
  settings.voice = false;
  saveSettings();
  voiceSuspend();
}

// 一時停止などで止める（ONの設定は残す）
function voiceSuspend() {
  clearTimeout(voice.restartTimer);
  if (voice.rec && voice.listening) {
    try { voice.rec.abort(); } catch (e) { /* noop */ }
  }
  voice.listening = false;
  el.mic.classList.remove('hearing');
  updateMicUI();
  applyVolume();
}

function updateMicUI() {
  el.mic.setAttribute('aria-pressed', String(voice.wanted));
  el.mic.classList.toggle('listening', voice.wanted && voice.listening);
  el.mic.setAttribute('aria-label', voice.wanted ? '音声入力をオフにする' : '音声入力をオンにする');
}

// レーベンシュタイン距離（上限を超えたら打ち切り）
function editDistance(a, b, max) {
  if (Math.abs(a.length - b.length) > max) return max + 1;
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    let rowMin = i;
    for (let j = 1; j <= b.length; j++) {
      const v = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
      cur.push(v);
      if (v < rowMin) rowMin = v;
    }
    if (rowMin > max) return max + 1;
    prev = cur;
  }
  return prev[b.length];
}

// 漢字まじりの聞き取り結果から、読みの正規表現を作る
function readingGroup(list) {
  const set = new Set();
  list.forEach((r) => {
    const k = loose(normalize(r));
    if (!k) return;
    set.add(k);
    if (/[つくちき]$/.test(k)) set.add(k.slice(0, -1) + 'つ'); // 促音化（鉄砲→てっぽう）
  });
  return set.size ? `(?:${Array.from(set).map(escRe).join('|')})` : '.{1,4}';
}
function singlesPattern(chars, prev) {
  return chars.map((c, j) => {
    if (c === '々') c = j > 0 ? chars[j - 1] : (prev || c); // 「々」は直前の漢字を繰り返す
    const r = KS.get(c);
    return r ? readingGroup(r) : '.{1,3}';
  }).join('');
}
function kanjiRegex(text) {
  const ch = Array.from(text);
  let out = '';
  let i = 0;
  while (i < ch.length) {
    if (isKanji(ch[i])) {
      let hit = false;
      for (let n = Math.min(6, ch.length - i); n >= 2; n--) {
        const w = ch.slice(i, i + n).join('');
        if (KC.has(w)) {
          const reads = KC.get(w);
          const cut = reads.filter((r) => r.length >= 3).map((r) => r.slice(0, -1)); // 送り仮名の重なり対策
          out += `(?:${readingGroup(reads.concat(cut)).slice(3, -1)}|${singlesPattern(ch.slice(i, i + n), ch[i - 1])})`;
          i += n;
          hit = true;
          break;
        }
      }
      if (!hit) { out += singlesPattern([ch[i]], ch[i - 1]); i++; }
    } else {
      out += escRe(loose(ch[i]));
      i++;
    }
  }
  try { return new RegExp(`^${out}$`); } catch (e) { return null; }
}

// 聞き取った1かたまりの文字から、技の候補を探す
function voiceCandidates(seg) {
  const t = normalize(seg);
  if (!t) return [];
  const exact = KEY_MAP.get(t);
  if (exact) return [exact];
  if (hasKanji(t)) {
    const re = kanjiRegex(t);
    if (!re) return [];
    const set = new Set();
    VOICE_KEYS.forEach((k) => { if (re.test(k.lkey)) set.add(k.move); });
    return Array.from(set);
  }
  return [];
}

function isOpen(move) { return game.targetIds.has(move.id) && !game.found.has(move.id); }

// 1つの聞き取り結果を判定 → { hits:[], dup, out }
function matchVoiceText(text) {
  const result = { hits: [], dup: null, out: null };
  const segs = String(text).split(/[\s、。,.!?！？]+/).filter(Boolean);
  const tryList = segs.length > 1 ? segs.concat([segs.join('')]) : segs;

  const judge = (cands) => {
    const open = cands.filter(isOpen);
    if (open.length === 1) { result.hits.push(open[0]); return true; }
    if (open.length > 1) return false; // 候補が複数あるときは決めない
    const known = cands.find((m) => game.targetIds.has(m.id));
    if (known) { result.dup = result.dup || known; return true; }
    if (cands.length) { result.out = result.out || cands[0]; return true; }
    return false;
  };

  tryList.forEach((seg, idx) => {
    if (idx === segs.length && result.hits.length) return; // 区切りごとに当たっていれば連結版は不要
    const t = normalize(seg);
    if (!t) return;
    if (judge(voiceCandidates(seg))) return;
    if (hasKanji(t)) return;

    // ひらがなの中に技名が含まれていないか（「えーと はたく」「はたくからてちょっぷ」など）
    const lt = loose(t);
    const inside = [];
    game.targets.forEach((m) => {
      if (!isOpen(m)) return;
      const k = loose(normalize(m.name));
      if (k.length >= 3 && lt.includes(k)) inside.push({ m, k });
    });
    inside.sort((a, b) => b.k.length - a.k.length);
    const used = [];
    inside.forEach(({ m, k }) => {
      const pos = lt.indexOf(k);
      const overlap = used.some(([s, e]) => pos < e && pos + k.length > s);
      if (!overlap) { used.push([pos, pos + k.length]); result.hits.push(m); }
    });
    if (inside.length) return;

    // 1〜2文字の聞き間違いを許す（未回答の技だけが対象）
    if (lt.length >= 3) {
      const max = lt.length >= 7 ? 2 : 1;
      let best = null, bestD = max + 1, tie = false;
      game.targets.forEach((m) => {
        if (!isOpen(m)) return;
        const d = editDistance(lt, loose(normalize(m.name)), max);
        if (d < bestD) { best = m; bestD = d; tie = false; } else if (d === bestD) tie = true;
      });
      if (best && bestD <= max && !tie) result.hits.push(best);
    }
  });
  result.hits = Array.from(new Set(result.hits));
  return result;
}

function handleVoice(alts) {
  if (!game || !game.running || game.ended) return;
  const heard = (alts[0] || '').trim();
  if (!heard) return;
  let fallback = null;
  for (const text of alts) {
    const r = matchVoiceText(text);
    if (r.hits.length) {
      r.hits.forEach((m) => { if (game && !game.ended) accept(m, true); });
      return;
    }
    if (!fallback && (r.dup || r.out)) fallback = r;
  }
  if (fallback && fallback.dup) {
    reject(`「${fallback.dup.name}」はもう答えています（聞き取り：${heard}）`, 'dup', true);
    flashTile(fallback.dup.id);
  } else if (fallback && fallback.out) {
    reject(outOfScopeText(fallback.out), 'ng', true);
  } else {
    reject(`「${heard}」は技名として聞き取れませんでした`, 'ng', true);
  }
}

/* =========================================================
   16. 一時停止・保存
   ========================================================= */
function pauseGame() {
  if (!game || game.ended || game.paused || !game.running) return;
  stopTimer();
  game.paused = true;
  resetCombo();
  voiceSuspend();
  bgm.stop();
  saveProgress();
  el.board.classList.add('is-hidden');
  el.answer.blur();
  showOverlay(el.ovPause);
}
function unpauseGame() {
  if (!game || game.ended) return;
  hideOverlay(el.ovPause);
  el.board.classList.remove('is-hidden');
  initAudio();
  resumeTimer();
  bgm.start();
  if (voice.wanted) voiceListen();
  focusAnswer();
}

function saveProgress() {
  if (!game || game.ended) return;
  if (game.running) accumulate();
  game.lastSaveAt = performance.now();
  store.set('save', {
    scope: game.scope,
    limit: game.limit,
    hint: game.hint,
    found: game.order,
    elapsed: Math.round(game.elapsed),
    maxCombo: game.maxCombo
  });
}

/* =========================================================
   17. 終了・結果
   ========================================================= */
async function endGame(reason) {
  if (!game || game.ended) return;
  stopTimer();
  game.ended = true;
  clearTimeout(game.cdTimer);
  resetCombo();
  voiceSuspend();
  bgm.stop();
  store.remove('save');
  el.answer.blur();
  el.answer.disabled = true;
  hideAllOverlays();

  const g = game; // 演出の待ち時間中に別のゲームが始まっても混ざらないように
  if (reason === 'complete') {
    sfx.groupDone();
    fx.confetti(140);
    await showBanner('コンプリート！', true, 1500);
  } else if (reason === 'timeup') {
    sfx.timeUp();
    await showBanner('タイムアップ！', false, 1300);
  }
  if (game !== g) return;
  showResult(reason);
}

function showResult(reason) {
  const total = game.targets.length;
  const count = game.found.size;
  const ratio = total ? count / total : 0;

  // 自己ベスト
  const bests = store.get('best', {});
  const key = bestKey(game.scope, game.limit);
  const prev = bests[key];
  const isComplete = count >= total;
  let isNew = false;
  if (count > 0 && (!prev || count > prev.count || (isComplete && prev.count >= total && game.elapsed < (prev.timeMs || Infinity)))) {
    isNew = true;
    bests[key] = { count, timeMs: isComplete ? Math.round(game.elapsed) : 0, date: Date.now() };
    store.set('best', bests);
  }

  const reasonText = { complete: 'コンプリート！', timeup: 'タイムアップ', giveup: 'ギブアップ' }[reason] || '';
  const rank = RANKS.find((r) => ratio >= r.min).name;
  el.resultReason.textContent = `${scopeLabel(game.scope)}・${limitLabel(game.limit)}　${reasonText}`;
  el.resultRank.textContent = rank;
  el.resultRank.classList.remove('stamp');
  el.resultTotal.textContent = total;
  el.resultSub.textContent = `正解率 ${(ratio * 100).toFixed(1)}%　${game.limit > 0 ? '使った時間' : 'かかった時間'} ${formatTime(game.elapsed)}　最大コンボ ${game.maxCombo}`;
  if (isNew) {
    el.resultBest.textContent = '自己ベスト更新！';
    el.resultBest.classList.add('new');
  } else {
    el.resultBest.textContent = prev ? `自己ベスト：${prev.count} / ${total}` : '';
    el.resultBest.classList.remove('new');
  }
  renderBreakdown();
  el.ovResult.dataset.share = `「ワザいえるかな？」${scopeLabel(game.scope)}（${limitLabel(game.limit)}）で ${count} / ${total} 個の技を言えた！【${rank}】`;

  // 盤面：言えなかった技を表示
  game.targets.forEach((m) => {
    if (!game.found.has(m.id)) {
      const t = game.tileEls.get(m.id);
      t.classList.add('missed');
      t.querySelector('.nm').textContent = m.name;
    }
  });
  game.groupEls.forEach((grp) => {
    grp.sec.classList.toggle('no-missed', grp.ids.every((id) => game.found.has(id)));
  });
  el.board.classList.remove('is-hidden');
  el.inputRow.hidden = true;
  el.feedback.hidden = true;
  el.lastCard.hidden = true;
  el.reviewRow.hidden = false;
  el.reviewTip.hidden = false;
  renderTimer();

  showOverlay(el.ovResult);
  sfx.result(isNew || ratio >= 0.5);
  if (isNew || ratio >= 0.5) setTimeout(() => fx.confetti(isNew ? 120 : 60), 300);

  // 数字のカウントアップ
  const startAt = performance.now();
  const dur = Math.min(1400, 300 + count * 15);
  const step = (now) => {
    const p = Math.min(1, (now - startAt) / dur);
    el.resultNum.textContent = Math.round(count * (1 - Math.pow(1 - p, 3)));
    if (p < 1) requestAnimationFrame(step);
    else {
      el.resultRank.classList.remove('stamp');
      void el.resultRank.offsetWidth;
      el.resultRank.classList.add('stamp');
    }
  };
  el.resultNum.textContent = '0';
  if (REDUCED_MOTION) el.resultNum.textContent = count; else requestAnimationFrame(step);
}

function renderBreakdown() {
  el.breakdown.textContent = '';
  const rows = [];
  if (game.scope.kind === 'gen') {
    TYPE_ORDER.forEach((t) => {
      const list = game.targets.filter((m) => m.type === t);
      if (list.length) rows.push({ label: TYPES[t].name, color: TYPES[t].color, list });
    });
  } else {
    for (let gg = 1; gg <= maxGen(); gg++) {
      const list = game.targets.filter((m) => m.gen === gg);
      if (list.length) rows.push({ label: GEN_LABEL(gg), color: '', list });
    }
  }
  const fills = [];
  rows.forEach((r) => {
    const n = r.list.filter((m) => game.found.has(m.id)).length;
    const row = document.createElement('div');
    row.className = 'bd-row';
    const lab = document.createElement('span');
    lab.textContent = r.label;
    const bar = document.createElement('div');
    bar.className = 'bd-bar';
    const fill = document.createElement('i');
    fill.style.width = '0%';
    if (r.color) fill.style.background = r.color;
    bar.appendChild(fill);
    const num = document.createElement('span');
    num.className = 'bd-num';
    num.textContent = `${n}/${r.list.length}`;
    row.appendChild(lab);
    row.appendChild(bar);
    row.appendChild(num);
    el.breakdown.appendChild(row);
    fills.push([fill, (n / r.list.length) * 100]);
  });
  // 少し遅らせて伸ばす（アニメーション）
  setTimeout(() => fills.forEach(([f, w]) => { f.style.width = `${w}%`; }), 60);
}

function shareResult() {
  const text = el.ovResult.dataset.share || '';
  const url = location.href.split('#')[0];
  const intent = `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}&hashtags=${encodeURIComponent('ワザいえるかな')}`;
  window.open(intent, '_blank', 'noopener');
}

/* =========================================================
   18. 技の詳細
   ========================================================= */
function openDetail(move) {
  const t = TYPES[move.type];
  el.detailTop.style.setProperty('--c', t.color);
  el.detailTop.style.setProperty('--on-c', t.on);
  el.detailNo.textContent = `No.${String(move.id).padStart(3, '0')}`;
  el.detailName.textContent = move.name;
  el.detailEn.textContent = '';
  el.detailBadges.textContent = '';
  const addBadge = (text, color, on) => {
    const b = document.createElement('span');
    b.className = 'badge';
    b.textContent = text;
    if (color) { b.style.background = color; b.style.color = on; }
    el.detailBadges.appendChild(b);
    return b;
  };
  addBadge(t.name, t.color, t.on);
  addBadge(GEN_LABEL(move.gen));
  const classBadge = addBadge('…');
  [el.detailPower, el.detailAcc, el.detailPp, el.detailPri].forEach((d) => { d.textContent = '…'; });
  el.detailDesc.textContent = '説明を読み込み中…';
  el.ovDetail.dataset.id = move.id;
  showOverlay(el.ovDetail);

  getDetail(move.id).then((d) => {
    if (el.ovDetail.dataset.id !== String(move.id)) return;
    el.detailEn.textContent = d.en || '';
    classBadge.textContent = DAMAGE_CLASS[d.c] || '—';
    el.detailPower.textContent = d.p != null ? d.p : '—';
    el.detailAcc.textContent = d.a != null ? d.a : '—';
    el.detailPp.textContent = d.pp != null ? d.pp : '—';
    el.detailPri.textContent = d.pr != null ? (d.pr > 0 ? `+${d.pr}` : d.pr) : '—';
    el.detailDesc.textContent = d.d || '説明文はありません';
  }).catch(() => {
    if (el.ovDetail.dataset.id !== String(move.id)) return;
    classBadge.textContent = '—';
    [el.detailPower, el.detailAcc, el.detailPp, el.detailPri].forEach((dd) => { dd.textContent = '—'; });
    el.detailDesc.textContent = '説明を取得できませんでした。通信環境を確認してください。';
  });
}

/* =========================================================
   19. オーバーレイ
   ========================================================= */
function showOverlay(ov) {
  ov.hidden = false;
  const btn = ov.querySelector('button');
  if (btn && window.matchMedia('(pointer: fine)').matches) setTimeout(() => btn.focus({ preventScroll: true }), 30);
}
function hideOverlay(ov) { ov.hidden = true; }
function hideAllOverlays() {
  [el.ovPause, el.ovConfirm, el.ovResult, el.ovDetail].forEach(hideOverlay);
}

/* =========================================================
   20. イベント
   ========================================================= */
function bindEvents() {
  // --- タイトル ---
  el.segKind.addEventListener('click', (e) => {
    const b = e.target.closest('button[data-kind]');
    if (!b) return;
    settings.kind = b.dataset.kind;
    saveSettings();
    renderSetup();
  });
  el.optVoice.addEventListener('change', () => { settings.voice = el.optVoice.checked; saveSettings(); });
  el.optHint.addEventListener('change', () => { settings.hint = el.optHint.checked; saveSettings(); });
  el.optDetail.addEventListener('change', () => { settings.detail = el.optDetail.checked; saveSettings(); });
  el.optSe.addEventListener('change', () => { settings.se = el.optSe.checked; saveSettings(); applyVolume(); });
  el.optBgm.addEventListener('change', () => { settings.bgm = el.optBgm.checked; saveSettings(); applyVolume(); });
  el.optSpeak.addEventListener('change', () => { settings.speak = el.optSpeak.checked; saveSettings(); });
  el.optVolume.addEventListener('input', () => {
    settings.volume = Number(el.optVolume.value);
    el.volumeVal.textContent = settings.volume;
    applyVolume();
  });
  el.optVolume.addEventListener('change', saveSettings);
  $('btn-sound-test').addEventListener('click', () => {
    initAudio();
    sfx.ok(3);
    setTimeout(() => sfx.groupDone(), 350);
  });

  const beginWithVoice = () => {
    // スマホはボタンを押した流れでないとマイク・キーボード・音が使えないので、ここでまとめて準備
    initAudio();
    voice.wanted = settings.voice && voice.supported;
    if (voice.wanted) { voice.fails = 0; voiceListen(); }
  };

  $('btn-start').addEventListener('click', () => {
    beginWithVoice();
    store.remove('save');
    startGame({ scope: scopeFrom(settings.kind, settings.gen, settings.type), limit: settings.limit, hint: settings.hint });
    if (!voice.wanted) el.answer.focus();
  });

  $('btn-resume').addEventListener('click', () => {
    const save = store.get('save', null);
    if (!isValidSave(save)) { renderResume(); return; }
    beginWithVoice();
    startGame({ scope: save.scope, limit: save.limit, hint: !!save.hint, found: save.found, elapsed: save.elapsed, maxCombo: save.maxCombo || 0 });
    if (!voice.wanted) el.answer.focus();
  });
  $('btn-discard').addEventListener('click', () => { store.remove('save'); renderResume(); });

  // --- 入力 ---
  el.answer.addEventListener('compositionstart', () => { composing = true; });
  el.answer.addEventListener('compositionend', () => { composing = false; setTimeout(tryAutoAccept, 0); });
  el.answer.addEventListener('input', (e) => {
    if (e.isComposing) return;
    el.answer.classList.remove('shake');
    tryAutoAccept();
  });
  el.answer.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter') return;
    if (e.isComposing || e.keyCode === 229 || composing) return; // 変換確定のEnterは無視
    e.preventDefault();
    submitAnswer();
  });
  $('btn-enter').addEventListener('click', () => { submitAnswer(); el.answer.focus(); });

  el.mic.addEventListener('click', () => {
    initAudio();
    if (voice.wanted && voice.listening) {
      voiceOff();
      sfx.mic(false);
      setFeedback('音声入力をオフにしました', '');
    } else {
      voiceOn();
      sfx.mic(true);
      setFeedback('マイクに向かって技名を言ってね', 'voice');
    }
  });

  // --- ゲーム中 ---
  $('btn-pause').addEventListener('click', pauseGame);
  $('btn-unpause').addEventListener('click', () => { unpauseGame(); if (!voice.wanted) el.answer.focus(); });
  $('btn-pause-title').addEventListener('click', () => { saveProgress(); goTitle(); });

  $('btn-giveup').addEventListener('click', () => {
    if (!game || game.ended || !game.running) return;
    stopTimer();
    game.paused = true;
    voiceSuspend();
    showOverlay(el.ovConfirm);
  });
  $('btn-confirm-yes').addEventListener('click', () => endGame('giveup'));
  $('btn-confirm-no').addEventListener('click', () => {
    hideOverlay(el.ovConfirm);
    resumeTimer();
    if (voice.wanted) voiceListen(); else el.answer.focus();
  });

  // マスをタップ → 詳細（正解済みのマス、終了後は全部）
  el.board.addEventListener('click', (e) => {
    const tile = e.target.closest('.tile');
    if (!tile || !game) return;
    if (!tile.classList.contains('found') && !tile.classList.contains('missed')) return;
    const move = MOVE_BY_ID.get(Number(tile.dataset.id));
    if (move) openDetail(move);
  });
  el.lastCard.addEventListener('click', () => {
    const move = MOVE_BY_ID.get(Number(el.lastCard.dataset.id));
    if (move) openDetail(move);
  });
  $('btn-detail-close').addEventListener('click', () => { hideOverlay(el.ovDetail); if (game && game.running) focusAnswer(); });
  el.ovDetail.addEventListener('click', (e) => { if (e.target === el.ovDetail) hideOverlay(el.ovDetail); });

  // --- 結果 ---
  $('btn-review').addEventListener('click', () => {
    hideOverlay(el.ovResult);
    window.scrollTo({ top: 0, behavior: REDUCED_MOTION ? 'auto' : 'smooth' });
  });
  $('btn-share').addEventListener('click', shareResult);
  const retry = () => {
    if (!game) return;
    const opt = { scope: game.scope, limit: game.limit, hint: game.hint };
    beginWithVoice();
    startGame(opt);
    if (!voice.wanted) el.answer.focus();
  };
  $('btn-retry').addEventListener('click', retry);
  $('btn-retry-review').addEventListener('click', retry);
  $('btn-title').addEventListener('click', goTitle);
  $('btn-title-review').addEventListener('click', goTitle);
  $('btn-show-result').addEventListener('click', () => showOverlay(el.ovResult));
  el.onlyMissed.addEventListener('click', () => {
    const on = !el.board.classList.contains('only-missed');
    el.board.classList.toggle('only-missed', on);
    el.onlyMissed.setAttribute('aria-pressed', String(on));
    el.onlyMissed.textContent = on ? 'すべて表示' : '言えなかった技だけ';
  });
  el.ovResult.addEventListener('click', (e) => { if (e.target === el.ovResult) hideOverlay(el.ovResult); });

  // ボタンを押したときの小さなクリック音
  document.addEventListener('click', (e) => {
    if (e.target.closest('.btn, .chip, .seg button, .icon-btn') && audio.ctx) sfx.click();
  });

  // --- キーボード：Esc ---
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    if (!el.ovDetail.hidden) { hideOverlay(el.ovDetail); return; }
    if (!game) return;
    if (!el.ovPause.hidden) { unpauseGame(); return; }
    if (!el.ovConfirm.hidden) { $('btn-confirm-no').click(); return; }
    if (!el.ovResult.hidden) { hideOverlay(el.ovResult); return; }
    if (!game.ended && el.screenGame.classList.contains('is-active')) pauseGame();
  });

  // タブ・アプリ切り替えで自動一時停止
  document.addEventListener('visibilitychange', () => {
    if (document.hidden && game && !game.ended && !game.paused && game.running && el.screenGame.classList.contains('is-active')) {
      pauseGame();
    }
  });
  window.addEventListener('pagehide', () => { if (game && !game.ended) saveProgress(); });

  // --- スマホ（Safari）の拡大・コピー対策 ---
  const isField = (t) => t instanceof HTMLInputElement || t instanceof HTMLTextAreaElement;
  document.addEventListener('gesturestart', (e) => e.preventDefault(), { passive: false });
  document.addEventListener('gesturechange', (e) => e.preventDefault(), { passive: false });
  document.addEventListener('dblclick', (e) => { if (!isField(e.target)) e.preventDefault(); }, { passive: false });
  let lastTouchEnd = 0;
  document.addEventListener('touchend', (e) => {
    const now = Date.now();
    if (now - lastTouchEnd <= 300 && !isField(e.target) && !e.target.closest('button, a, label')) e.preventDefault();
    lastTouchEnd = now;
  }, { passive: false });
  document.addEventListener('contextmenu', (e) => { if (!isField(e.target)) e.preventDefault(); });
  document.addEventListener('selectstart', (e) => { if (!isField(e.target)) e.preventDefault(); });
}

/* =========================================================
   21. 起動
   ========================================================= */
function init() {
  fx.init();
  buildHeroMosaic();
  renderSetup();
  renderResume();
  updateMicUI();
  bindEvents();
  checkNewMoves();
}
init();
